	if tc.logger == nil {
		t.Error("nil logger should be replaced with default")
	}
}

func TestCount_EmptyString(t *testing.T) {
	tc := NewTokenCounter("cl100k_base", slog.Default())
	if got := tc.Count(""); got != 0 {
		t.Errorf("Count(\"\") = %d, want 0", got)
	}
}

